import unittest
from candidate import below_threshold

class TestBelowThreshold(unittest.TestCase):
    def test_below_threshold_empty_list(self):
        self.assertTrue(below_threshold([]))

    def test_below_threshold_no_elements(self):
        self.assertTrue(below_threshold([], 100))

    def test_below_threshold_below_threshold(self):
        self.assertTrue(below_threshold([1, 2, 4, 10], 100))

    def test_below_threshold_above_threshold(self):
        self.assertFalse(below_threshold([1, 20, 4, 10], 5))

    def test_below_threshold_threshold_is_zero(self):
        self.assertTrue(below_threshold([0], 0))

    def test_below_threshold_threshold_is_negative(self):
        self.assertTrue(below_threshold([-1, -2, -3], -5))

    def test_below_threshold_threshold_is_greater_than_all_numbers(self):
        self.assertTrue(below_threshold([1, 2, 3], 1000))

    def test_below_threshold_all_numbers_equal_to_threshold(self):
        self.assertTrue(below_threshold([10, 10, 10], 10))

    def test_below_threshold_mixed_numbers(self):
        self.assertTrue(below_threshold([1, 10, 4, 10], 10))

    def test_below_threshold_none_values(self):
        self.assertRaises(TypeError, lambda: below_threshold([None, 10], 10))

    def test_below_threshold_list_type_error(self):
        self.assertRaises(TypeError, lambda: below_threshold("not_a_list", 10))

    def test_below_threshold_threshold_type_error(self):
        self.assertRaises(TypeError, lambda: below_threshold([1, 2, 3], "not_an_int")
